          '"use client";\n\nimport { cn } from "@/lib/utils";\nimport {\n  AnimatePresence,\n  LayoutGroup,\n  motion,\n  type Transition,\n  useReducedMotion,\n  type Variants,\n} from "motion/react";\nimport {\n  type ComponentPropsWithoutRef,\n  type CSSProperties,\n  type ElementType,\n  useEffect,\n  useId,\n  useMemo,\n  useRef,\n} from "react";\n\nconst NBSP = "\\u00A0";\n\nconst TEXT_MORPH_VARIANTS = {\n  blur: {\n    initial: { opacity: 0, y: 6, filter: "blur(6px)" },\n    animate: { opacity: 1, y: 0, filter: "blur(0px)" },\n    exit: { opacity: 0, y: -6, filter: "blur(6px)" },\n  },\n  slide: {\n    initial: { opacity: 0, y: 8 },\n    animate: { opacity: 1, y: 0 },\n    exit: { opacity: 0, y: -8 },\n  },\n} as const satisfies Record<string, Variants>;\n\nconst DEFAULT_VARIANTS: Variants = {\n  initial: { opacity: 0 },\n  animate: { opacity: 1 },\n  exit: { opacity: 0 },\n};\n\nconst DEFAULT_TRANSITION: Transition = {\n  type: "spring",\n  stiffness: 280,\n  damping: 18,\n  mass: 0.3,\n};\n\nexport type TextMorphVariant = keyof typeof TEXT_MORPH_VARIANTS;\n\nexport type TextMorphProps = {\n  /** String label to morph between updates. */\n  children: string;\n  as?: ElementType;\n  className?: string;\n  /** Class names applied to each animated character span. */\n  charClassName?: string;\n  style?: CSSProperties;\n  variants?: Variants;\n  transition?: Transition;\n  /** Optional preset when `variants` is omitted. Default motion matches opacity crossfade + layoutId morph. */\n  variant?: TextMorphVariant;\n  /**\n   * Per-character delay in seconds.\n   * @default 0\n   */\n  staggerDelay?: number;\n  /**\n   * Keep same-index glyphs static instead of layout-morphing shared letters.\n   * @default false\n   */\n  skipUnchanged?: boolean;\n  /**\n   * Live region politeness when the label updates.\n   * @default "off"\n   */\n  live?: "assertive" | "off" | "polite";\n} & Omit<ComponentPropsWithoutRef<"p">, "children">;\n\nexport function TextMorph({\n  children,\n  as: Component = "p",\n  className,\n  charClassName,\n  style,\n  variants,\n  transition,\n  variant,\n  staggerDelay = 0,\n  skipUnchanged = false,\n  live = "off",\n  ...props\n}: TextMorphProps) {\n  const uniqueId = useId();\n  const prefersReducedMotion = useReducedMotion();\n  const previousTextRef = useRef<string | null>(null);\n  const previousIdsRef = useRef<Set<string>>(new Set());\n\n  const characters = useMemo(() => {\n    const charCounts: Record<string, number> = {};\n\n    return children.split("").map((char) => {\n      const lowerChar = char.toLowerCase();\n      charCounts[lowerChar] = (charCounts[lowerChar] || 0) + 1;\n\n      return {\n        id: `${uniqueId}-${lowerChar}${charCounts[lowerChar]}`,\n        label: char === " " ? NBSP : char,\n      };\n    });\n  }, [children, uniqueId]);\n\n  const previousText = previousTextRef.current;\n  const previousIds = previousIdsRef.current;\n  const resolvedVariants =\n    variants ?? (variant ? TEXT_MORPH_VARIANTS[variant] : DEFAULT_VARIANTS);\n  const resolvedTransition = transition ?? DEFAULT_TRANSITION;\n\n  useEffect(() => {\n    previousTextRef.current = children;\n    previousIdsRef.current = new Set(\n      characters.map((character) => character.id)\n    );\n  }, [children, characters]);\n\n  if (prefersReducedMotion) {\n    return (\n      <Component\n        aria-live={live === "off" ? undefined : live}\n        className={cn(className)}\n        style={style}\n        {...props}\n      >\n        {children}\n      </Component>\n    );\n  }\n\n  return (\n    <Component\n      aria-label={children}\n      aria-live={live === "off" ? undefined : live}\n      className={cn("relative", className)}\n      style={style}\n      {...props}\n    >\n      <LayoutGroup id={uniqueId}>\n        <AnimatePresence mode="popLayout">\n          {characters.map((character, index) => {\n            if (skipUnchanged) {\n              const previousChar = previousText?.[index];\n              const currentChar = children[index];\n\n              if (\n                previousText !== null &&\n                index < previousText.length &&\n                previousChar === currentChar\n              ) {\n                return (\n                  <motion.span\n                    aria-hidden\n                    className={cn("inline-block", charClassName)}\n                    key={character.id}\n                    layout="position"\n                    layoutId={character.id}\n                    transition={resolvedTransition}\n                  >\n                    {character.label}\n                  </motion.span>\n                );\n              }\n            }\n\n            const isEntering =\n              previousText !== null && !previousIds.has(character.id);\n\n            return (\n              <motion.span\n                animate="animate"\n                aria-hidden\n                className={cn("inline-block", charClassName)}\n                exit="exit"\n                initial={isEntering ? "initial" : false}\n                key={character.id}\n                layout="position"\n                layoutId={character.id}\n                transition={\n                  staggerDelay > 0\n                    ? { ...resolvedTransition, delay: index * staggerDelay }\n                    : resolvedTransition\n                }\n                variants={resolvedVariants}\n              >\n                {character.label}\n              </motion.span>\n            );\n          })}\n        </AnimatePresence>\n      </LayoutGroup>\n    </Component>\n  );\n}',
